import React, { useState } from 'react'

function Toggle() {
  const [on, setOn] = useState(false)
  const flip = () => setOn(prev => !prev)
  return (
    <div>
      <p>{on ? 'ON' : 'OFF'}</p>
      <button onClick={flip}>Toggle</button>
    </div>
  )
}

// After first click: <p>ON</p>
// After second click: <p>OFF</p>
The component initializes on to false, rendering "OFF". Each click calls flip, which uses the functional updater to invert the previous value, guaranteeing correct toggling even if React batches the updates.

