function Button({variant, children, ...rest}) {
  const style = {
    backgroundColor: variant === 'primary' ? '#0066ff' : '#e0e0e0',
    color: variant === 'primary' ? '#fff' : '#000',
    border: 'none',
    padding: '8px 12px',
    cursor: 'pointer'
  }
  return <button style={style} {...rest}>{children}</button>
}

Trade‑off: Inline style objects keep the styling logic in JavaScript, making it easy to compute colors based on props without extra CSS files, but they cannot use pseudo‑classes (e.g., :hover) or media queries without additional libraries. CSS classes keep styling separate, allow full CSS features, and enable caching by the browser, but require managing class name strings and may need a mapping function to select the correct class based on the variant.

Steps: 1) When the modal opens, store the element that had focus. 2) Use a ref on the modal container. 3) In a useEffect that runs on open, query the container for the first focusable element (e.g., button, input, [tabindex="0"]). 4) Call .focus() on that element. 5) On unmount, restore focus to the previously stored element.

// Snippet
function Modal({open, onClose}) {
  const modalRef = React.useRef(null);
  const prevFocus = React.useRef(null);
  React.useEffect(() => {
    if (open) {
      prevFocus.current = document.activeElement;
      const first = modalRef.current.querySelector('button, [href], input, select, textarea, [tabindex]:not([tabindex="-1"])');
      first && first.focus();
      return () => prevFocus.current && prevFocus.current.focus();
    }
  }, [open]);
  if (!open) return null;
  return (
    <div role="dialog" aria-modal="true" ref={modalRef}>
      <button onClick={onClose}>Close</button>
    </div>
  );
}
